function advect(b, d, d0, u0, v0) {
	var i0, j0, i1, j1;
	var x, y, s0, t0, s1, t1, dt0;
	dt0 = dt * Nx;
	for (var i=1 ; i<=Nx ; i++) {
		for (var j=1 ; j<=Ny ; j++) {
			x = i - dt0 * u0[i][j];
			y = j - dt0 * v0[i][j];
			if (x<0.5) x = 0.5;
			if (x>Nx+0.5) x = Nx+0.5;
			i0 = int(x);
			i1 = i0 + 1;
			if (y<0.5) y = 0.5;
			if (y>Ny+0.5) y = Ny+0.5;
			j0 = int(y);
			j1 = j0 + 1;
			s1 = x - i0;
			s0 = 1 - s1;
			t1 = y - j0;
			t0 = 1 - t1;
			d[i][j] = s0 * (t0 * d0[i0][j0] + t1 * d0[i0][j1]) + s1 * (t0 * d0[i1][j0] + t1 * d0[i1][j1]);
		}
	}
	set_bnd(b, d);
}


