function project(u0, v0, p, div) {
	var h = 1.0 / Nx;
	for (var i=1; i<=Nx ; i++) {
		for (var j=1; j<=Ny ; j++) {
			div[i][j] = -0.5 * h * (u0[i + 1][j] - u0[i - 1][j] + v0[i][j + 1] - v0[i][j - 1]);
			p[i][j] = 0;
		}
	}
	set_bnd(0, div);
	set_bnd(0, p);
	for (var k = 0; k < 10; k++) {
		for (i=1; i<=Nx ; i++) {
			for (j=1; j<=Ny ; j++) {
				p[i][j] = (div[i][j] + p[i - 1][j] + p[i + 1][j] + p[i][j - 1] + p[i][j + 1]) * (1 / 4);
			}
		}
		set_bnd(0, p);
	}
	// to do: <u,v> * n == 0
	for (i=1 ; i<=Nx ; i++) {
		for (j=1 ; j<=Ny ; j++) {
			u0[i][j] -= 0.5 * (p[i + 1][j] - p[i - 1][j]) / h;
			v0[i][j] -= 0.5 * (p[i][j + 1] - p[i][j - 1]) / h;
		}
	}
	set_bnd(1, u0);
	set_bnd(2, v0);
}


